body.raw:
{
  "documents": [
    { "url": "https://erp.elbrit.org{{billPath}}", "headers": { "Authorization": "{{erpToken}}" } }
  ],
  "context": "Employee expense claim in India, amounts in INR. Expense: Travel / Fuel.",
  "fields": {
    "amount":   { "type": "number", "expected": 500, "weight": 70, "tolerance": "2%", "description": "the final total paid on the bill" },
    "date":     { "type": "date", "expected": "2026-10-20", "weight": 15, "toleranceDays": 3, "description": "the bill or transaction date" },
    "category": { "type": "text", "expected": "Travel / Fuel", "match": "meaning", "weight": 15, "description": "what the bill is for" },
    "vendor":   { "type": "text", "description": "the shop or company that issued the bill" }
  },
  "rules": ["It must be a bill, receipt, ticket or invoice -- not a selfie, a blank page or an unrelated photo"],
  "bands": { "low": 90, "medium": 70 }
}

{
  "documents": [ { "url": "{{billUrl}}" } ],
  "context": "Employee expense claim in India, amounts in INR. Expense: Food.",
  "fields": {
    "amount":   { "type": "number", "expected": 350, "weight": 70, "tolerance": "2%" },
    "date":     { "type": "date", "expected": "2026-10-20", "weight": 15, "toleranceDays": 3 },
    "category": { "type": "text", "expected": "Food", "match": "meaning", "weight": 15 },
    "vendor":   { "type": "text" }
  }
}
